import hashlib,json,subprocess
rows=json.loads("[{\"sha\":\"ca9ead3e3a0515e5f9be4191a7b38afff6c28f8f\",\"paths\":[\"CONTRIBUTING.md\"],\"source\":\"# Contributing to Public Commons Sprint Assets\\n\\nThank you for helping maintain and extend these public goods.\\n\\n## Principles\\n- Keep assets factual, sourced from public/open materials, and free of personal data.\\n- Prefer permissive licenses (MIT, Apache-2.0, CC-BY-4.0, CC0).\\n- Mark any domain-specific or high-stakes content with \\\"Needs expert review\\\".\\n- Include verification notes and known limitations.\\n- Write for underserved users: plain language, offline-friendly where possible, accessibility considered.\\n\\n## How to contribute\\n1. Open an issue describing the improvement or new asset.\\n2. Fork, make changes on a branch, open a pull request.\\n3. For new prompts/templates: include a short test case or example usage.\\n4. For code: include basic tests or runnable examples if feasible.\\n5. Update the relevant README and LICENSE notes.\\n\\n## Priority areas post-sprint\\n- Translations / localization of OER and glossaries (with native-speaker review)\\n- Additional datasheets for public datasets\\n- More offline-friendly formats\\n- Evaluation results and community feedback incorporation\\n- Maintenance of existing modules\\n\\n## Code of Conduct\\nBe respectful. Focus on the work. No harassment, spam, or off-topic political advocacy.\\n\\nQuestions? Open an issue.\\n\"},{\"sha\":\"b8cc6ff2c08ae0869b3822917916fe4a868d5cf8\",\"paths\":[\"README.md\"],\"source\":\"# Public Commons Sprint 2026\\n\\nDurable, openly reusable public-good assets generated during a focused 48-hour sprint using Grok (xAI) surfaces.\\n\\n**Goal**: Convert remaining SuperGrok Heavy allowance into GitHub-first, human-auditable, maintainable resources for underserved communities (low-connectivity educators, small nonprofits, Global South researchers, disability communities, local resilience groups, civic technologists).\\n\\n## License\\nMIT for code and most technical assets. CC-BY-4.0 or CC0 for educational content, prompts, and documentation where noted in individual folders. See LICENSE and per-folder notes.\\n\\n## Structure (initial)\\n- `/prompts/` — Reusable public-goods prompt library (Top priority asset)\\n- `/oer/` — Offline-first AI literacy and education modules\\n- `/accessibility/` — WCAG checklists, remediation templates, audit scripts\\n- `/nonprofit-ops/` — Operations templates, checklists, spreadsheets\\n- `/datasets/` — AI-ready datasheets and cleaning scripts for public data\\n- `/agents/` — Reusable AI-agent skills and infrastructure patterns\\n- `/media-literacy/` — Fact-checking and media literacy modules\\n- `/resilience/` — Local climate and environmental resilience playbooks/templates\\n- `/docs/` — Process documentation, verification notes, contribution guide\\n\\n## Principles\\n- Public / open sources only\\n- No personal data collection\\n- Explicit \\\"Needs expert review\\\" flags for synthesis, translations, domain-specific claims\\n- Human-auditable and maintainable after the sprint\\n- Bias toward assets usable by underserved communities\\n\\n## Verification\\nAll outputs include source notes, test cases where applicable, and known limitations. See CONTRIBUTING.md and individual READMEs.\\n\\n## How to contribute\\nSee CONTRIBUTING.md. Prefer issues and PRs. This sprint ends ~26 Aug 2026; ongoing maintenance is community-driven.\\n\\n## Local delivery\\n\\nGitHub Actions jobs are disabled in source. Use the existing project commands in a\\nlocal or cloud Linux runtime. The [local delivery guide](.github/HOSTED_COMPUTE.md)\\nincludes the original source export command, retained workflow recipes and policy.\\n\\nGenerated as part of the Public Commons Sprint, August 2026.\\n\\n## PermitPulse paid pilot\\n\\nSee `permitpulse_pilot/` for the commercialization-only synthetic pilot carrier. Predecessor `permitpulse-all-gas` submission receipts remain OPEN and `readyForSubmission` remains false.\\n\\n## October 2026: PayPal AI competition projects\\n\\nFive runnable application candidates now live in this public repository: [ClaimProof Commerce](claimproof-commerce/README.md), [DisburseLens](paypal-disburselens-2026/README.md), [RenewalGuard](paypal-renewalguard-2026/README.md), [CartWitness](paypal26-cartwitness/README.md), and [DisputeLedger](paypal26-disputeledger/README.md).\\n\\n[View the judge-entry guide](docs/PAYPAL_AI_2026_ENTRY_READINESS.md) for run commands, source references and required entry steps. These public prototypes are not verified Devpost submissions. The contest deadline is November 12, 2026, noon PST.\\n\"},{\"sha\":\"f6579d64e71c99588e34685022886287841b815b\",\"paths\":[\"public-metadata-cleanup.json\"],\"source\":\"{\\n  \\\"schema\\\": \\\"public-github-metadata-cleanup/v1\\\",\\n  \\\"repository\\\": \\\"woahwhattheheck/public-commons-sprint-2026\\\",\\n  \\\"policy_generation\\\": \\\"public-metadata-isolation/v1\\\",\\n  \\\"items\\\": [\\n    {\\n      \\\"kind\\\": \\\"issue\\\",\\n      \\\"number\\\": 114,\\n      \\\"field\\\": \\\"body\\\",\\n      \\\"state\\\": \\\"REDACTION_REQUIRED\\\",\\n      \\\"reasons\\\": [\\n        \\\"commons-work-item-lineage\\\",\\n        \\\"internal-commit-locator\\\",\\n        \\\"internal-swarm-lineage\\\"\\n      ],\\n      \\\"preserve\\\": [\\n        \\\"OneWriter product scope\\\",\\n        \\\"transactional lease architecture\\\",\\n        \\\"retained identifier semantics\\\",\\n        \\\"deployment and external-authority hard gates\\\"\\n      ],\\n      \\\"redact\\\": [\\n        \\\"internal work-item locator\\\",\\n        \\\"internal commit locator\\\",\\n        \\\"internal orchestration identity\\\"\\n      ]\\n    }\\n  ]\\n}\\n\"},{\"sha\":\"c0cf8be92c516cda4b522a65a909f787b8b11556\",\"paths\":[\"test_external_surface_isolation.py\"],\"source\":\"from __future__ import annotations\\n\\nimport json\\nimport tempfile\\nimport unittest\\nfrom unittest.mock import patch\\nfrom pathlib import Path\\nfrom urllib.parse import quote\\n\\nfrom scripts import check_external_surface_isolation as guard\\n\\n\\nclass ExternalSurfaceIsolationTests(unittest.TestCase):\\n    def test_missing_root_and_obfuscated_marker_fail_closed(self) -> None:\\n        with tempfile.TemporaryDirectory() as td:\\n            root = Path(td)\\n            with self.assertRaises(guard.ScanError):\\n                guard.scan_root(root / \\\"missing\\\")\\n            obfuscated = (\\n                \\\"https://github.com/woahwhattheheck\\\"\\n                + \\\"%26%23x2f%3Bcomm%26%23x200b%3Bons\\\"\\n            )\\n            (root / \\\"index.html\\\").write_text(obfuscated + \\\"\\\\n\\\", encoding=\\\"utf-8\\\")\\n            _, findings = guard.scan_root(root)\\n            self.assertEqual(len(findings), 1)\\n            self.assertEqual(findings[0][2], \\\"commons-repository\\\")\\n\\n    def test_source_escapes_and_encoded_invisibles_cannot_hide_marker(self) -> None:\\n        repo = \\\"woahwhattheheck\\\" + \\\"/commons\\\"\\n        cases = (\\n            \\\"woahwhattheheck\\\" + r\\\"\\\\u002fcommons\\\",\\n            \\\"woahwhattheheck\\\" + r\\\"\\\\x2fcommons\\\",\\n            \\\"woahwhattheheck\\\" + r\\\"\\\\u{2f}commons\\\",\\n            \\\"woahwhattheheck\\\" + r\\\"\\\\/commons\\\",\\n            \\\"woahwhattheheck\\\" + \\\"%E2%80%8B/commons\\\",\\n            \\\"woahwhattheheck\\\" + \\\"&#8203;/commons\\\",\\n        )\\n        for case in cases:\\n            normalized = guard.normalized_for_scan(case)\\n            self.assertIn(repo, normalized)\\n\\n    def test_marker_boundaries_avoid_owner_and_repo_prefix_false_positives(self) -> None:\\n        clean = (\\n            \\\"https://github.com/notwoahwhattheheck/commons\\\",\\n            \\\"https://github.com/woahwhattheheck/commons-demo\\\",\\n        )\\n        for case in clean:\\n            candidate = guard.normalized_for_scan(case)\\n            self.assertFalse(\\n                any(guard.marker_present(candidate, marker) for _, marker in guard.FORBIDDEN_MARKERS)\\n            )\\n\\n        target = \\\"woahwhattheheck\\\" + \\\"/commons.git\\\"\\n        candidate = guard.normalized_for_scan(\\\"git@github.com:\\\" + target)\\n        self.assertTrue(guard.marker_present(candidate, guard.FORBIDDEN_MARKERS[0][1]))\\n\\n    def test_normalization_exhaustion_fails_closed(self) -> None:\\n        value = \\\"woahwhattheheck\\\" + \\\"/commons\\\"\\n        for _ in range(guard.MAX_NORMALIZATION_PASSES + 2):\\n            value = quote(value, safe=\\\"\\\")\\n        with self.assertRaisesRegex(guard.ScanError, \\\"normalization pass limit\\\"):\\n            guard.normalized_for_scan(value)\\n\\n    def test_scan_reports_normalization_exhaustion_as_blocking_line(self) -> None:\\n        with tempfile.TemporaryDirectory() as td:\\n            root = Path(td)\\n            value = \\\"woahwhattheheck\\\" + \\\"/commons\\\"\\n            for _ in range(guard.MAX_NORMALIZATION_PASSES + 2):\\n                value = quote(value, safe=\\\"\\\")\\n            (root / \\\"surface.txt\\\").write_text(value + \\\"\\\\n\\\", encoding=\\\"utf-8\\\")\\n            _, findings = guard.scan_root(root)\\n            self.assertEqual(len(findings), 1)\\n            self.assertEqual(findings[0][0:2], (\\\"surface.txt\\\", 1))\\n            self.assertTrue(findings[0][2].startswith(\\\"unscannable-public-line:normalization pass limit\\\"))\\n\\n    def test_scan_flags_json_unicode_escaped_commons_path(self) -> None:\\n        with tempfile.TemporaryDirectory() as td:\\n            root = Path(td)\\n            escaped = \\\"woahwhattheheck\\\" + r\\\"\\\\u002fcommons\\\"\\n            (root / \\\"surface.json\\\").write_text('{\\\"url\\\":\\\"' + escaped + '\\\"}\\\\n', encoding=\\\"utf-8\\\")\\n            _, findings = guard.scan_root(root)\\n            self.assertEqual(len(findings), 1)\\n            self.assertEqual(findings[0][2], \\\"commons-repository\\\")\\n\\n    def test_internal_slack_and_svg_xml_surfaces_are_blocking(self) -> None:\\n        with tempfile.TemporaryDirectory() as td:\\n            root = Path(td)\\n            slack = \\\"https://tokenjunkielabs.slack.com\\\" + \\\"/archives/C0EXAMPLE/p123\\\"\\n            (root / \\\"diagram.svg\\\").write_text(\\n                '<svg><a href=\\\"' + slack + '\\\">internal</a></svg>\\\\n',\\n                encoding=\\\"utf-8\\\",\\n            )\\n            (root / \\\"feed.xml\\\").write_text(\\n                '<link href=\\\"' + slack.replace(\\\"/archives/\\\", \\\"%2Farchives%2F\\\") + '\\\"/>\\\\n',\\n                encoding=\\\"utf-8\\\",\\n            )\\n            checked, findings = guard.scan_root(root)\\n            self.assertEqual(checked, 2)\\n            self.assertEqual(\\n                [finding[2] for finding in findings],\\n                [\\\"internal-slack-archive\\\", \\\"internal-slack-archive\\\"],\\n            )\\n\\n    def test_symlinked_public_directory_fails_closed(self) -> None:\\n        with tempfile.TemporaryDirectory() as td:\\n            root = Path(td)\\n            target = root / \\\"target\\\"\\n            target.mkdir()\\n            (target / \\\"README.md\\\").write_text(\\\"clean\\\\n\\\", encoding=\\\"utf-8\\\")\\n            link = root / \\\"linked-public\\\"\\n            try:\\n                link.symlink_to(target, target_is_directory=True)\\n            except (OSError, NotImplementedError):\\n                self.skipTest(\\\"directory symlink unavailable\\\")\\n            with self.assertRaisesRegex(guard.ScanError, \\\"symlinked public directory\\\"):\\n                guard.scan_root(root)\\n\\n    def test_walk_traversal_error_fails_closed(self) -> None:\\n        with tempfile.TemporaryDirectory() as td:\\n            root = Path(td)\\n\\n            def broken_walk(_root, *, topdown, onerror, followlinks):\\n                self.assertTrue(topdown)\\n                self.assertFalse(followlinks)\\n                error = OSError(\\\"simulated traversal failure\\\")\\n                error.filename = str(root / \\\"raced-subtree\\\")\\n                onerror(error)\\n                return iter(())\\n\\n            with patch.object(guard.os, \\\"walk\\\", broken_walk):\\n                with self.assertRaisesRegex(guard.ScanError, \\\"cannot traverse public directory\\\"):\\n                    guard.scan_root(root)\\n\\n    def test_unscannable_public_text_is_blocking(self) -> None:\\n        with tempfile.TemporaryDirectory() as td:\\n            root = Path(td)\\n            (root / \\\"README.md\\\").write_bytes(b\\\"\\\\xff\\\\xfe\\\")\\n            _, findings = guard.scan_root(root)\\n            self.assertTrue(findings)\\n            self.assertEqual(findings[0][2], \\\"unscannable-public-text\\\")\\n\\n    def test_notebook_json_is_scanned(self) -> None:\\n        with tempfile.TemporaryDirectory() as td:\\n            root = Path(td)\\n            target = \\\"woahwhattheheck\\\" + \\\"/commons\\\"\\n            notebook = {\\n                \\\"cells\\\": [\\n                    {\\n                        \\\"cell_type\\\": \\\"markdown\\\",\\n                        \\\"metadata\\\": {},\\n                        \\\"source\\\": [\\\"Internal docs: https://github.com/\\\" + target],\\n                    }\\n                ],\\n                \\\"metadata\\\": {},\\n                \\\"nbformat\\\": 4,\\n                \\\"nbformat_minor\\\": 5,\\n            }\\n            (root / \\\"public.ipynb\\\").write_text(\\n                json.dumps(notebook, sort_keys=True) + \\\"\\\\n\\\",\\n                encoding=\\\"utf-8\\\",\\n            )\\n            checked, findings = guard.scan_root(root)\\n            self.assertEqual(checked, 1)\\n            self.assertEqual([finding[2] for finding in findings], [\\\"commons-repository\\\"])\\n\\n    def test_extensionless_public_text_is_scanned(self) -> None:\\n        with tempfile.TemporaryDirectory() as td:\\n            root = Path(td)\\n            (root / \\\"Dockerfile\\\").write_text(\\\"FROM python:3.13\\\\n\\\", encoding=\\\"utf-8\\\")\\n            checked, findings = guard.scan_root(root)\\n            self.assertEqual((checked, findings), (1, []))\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    unittest.main(verbosity=2)\\n\"},{\"sha\":\"f04109a22bc05882bbb82ba02d041fef8c79725b\",\"paths\":[\"stellar/scf-starforge-20261009/sf30-seller-sdk/rest-methods-acceptance.mjs\"],\"source\":\"// MIT. One focused original-source REST serving and handoff exercise.\\n// Native payment is a controlled collaborator; no signer, provider or ledger.\\nimport assert from 'node:assert/strict';\\nimport { createServer } from 'node:http';\\nimport { mkdtemp, readFile, writeFile, rm } from 'node:fs/promises';\\nimport { tmpdir } from 'node:os';\\nimport { join } from 'node:path';\\nimport { run as importService } from '../sf61-openapi-seller-import/cli.mjs';\\nimport { readSellerConfig, startSellerService } from './serve.mjs';\\nimport { createUpstreamApplication } from './upstream.mjs';\\nimport { requiresJsonBody } from './http-methods.mjs';\\nimport { startSellerOperations } from './operations/server.mjs';\\nimport { captureBundle } from '../sf93-seller-support-bundle/bundle.mjs';\\nimport { run as auditSeller, planProbes } from '../sf96-seller-acceptance/audit.mjs';\\n\\nconst methods = ['GET', 'HEAD', 'POST', 'PUT', 'PATCH', 'DELETE'];\\nconst root = await mkdtemp(join(tmpdir(), 'sf30-rest-methods-'));\\nconst sessions = [], backends = [];\\nconst json = async (path, value) => writeFile(path, JSON.stringify(value), { mode: 0o600, flag: 'wx' });\\nconst parsed = async path => JSON.parse(await readFile(path, 'utf8'));\\nconst response = async (url, init) => {\\n  const value = await fetch(url, { ...init, redirect: 'error', signal: AbortSignal.timeout(5000) });\\n  const body = await value.text();\\n  return { status: value.status, headers: value.headers, body };\\n};\\n\\ntry {\\n  const quantity = { type: 'integer', minimum: 0, examples: [1] };\\n  const resultSchema = { type: 'object', properties: { item: { type: 'object',\\n    properties: { quantity }, required: ['quantity'], additionalProperties: false } },\\n    required: ['item'], additionalProperties: false };\\n  const operations = Object.fromEntries(methods.map(method => [method.toLowerCase(), {\\n    operationId: method.toLowerCase() + 'Item', summary: method + ' an inventory item',\\n    ...(requiresJsonBody(method) ? { requestBody: { required: true, content: {\\n      'application/json': { schema: { type: 'object', properties: { quantity },\\n        required: ['quantity'], additionalProperties: false }, example: { quantity: 1 } },\\n    } } } : {}),\\n    responses: { [method === 'DELETE' ? '204' : '200']: { description: 'Local application response',\\n      ...(['HEAD', 'DELETE'].includes(method) ? {} : { content: {\\n        'application/json': { schema: resultSchema } } }),\\n    } },\\n  }]));\\n  const spec = { openapi: '3.1.1', info: { title: 'Local REST integration', version: '1' },\\n    servers: [{ url: 'https://seller.example/api' }], paths: { '/items/{sku}': {\\n      parameters: [\\n        { in: 'path', name: 'sku', required: true, schema: { type: 'string', minLength: 1 }, example: 'SKU-1' },\\n        { in: 'query', name: 'version', required: true, schema: { type: 'integer', minimum: 1 }, example: 1 },\\n      ], ...operations,\\n    } } };\\n  const payment = { scheme: 'exact', network: 'stellar:testnet', amount: '7',\\n    asset: 'LOCAL_NONPAYABLE_ASSET', payTo: 'LOCAL_NONPAYABLE_RECIPIENT', maxTimeoutSeconds: 60 };\\n  const options = [payment, { ...payment, amount: '11', asset: 'LOCAL_NONPAYABLE_ASSET_ALTERNATIVE',\\n    extra: { reference: 'preserve-this-original-choice' } }];\\n  const selections = methods.map(method => ({ method, path: '/items/{sku}', accepts: options }));\\n  const bindings = methods.map(method => ({ id: method.toLowerCase() + 'Item',\\n    method, path: '/items/{sku}', handler: method.toLowerCase() + 'Item', validateInput: true }));\\n  for (const [name, value] of [['spec', spec], ['selections', selections], ['bindings', bindings]])\\n    await json(join(root, name + '.json'), value);\\n  const observed = [];\\n  let item = { quantity: 1 };\\n  const backend = createServer(async (req, res) => {\\n    try {\\n      const chunks = [];\\n      for await (const chunk of req) chunks.push(chunk);\\n      const bytes = Buffer.concat(chunks), target = new URL(req.url, 'http://127.0.0.1');\\n      observed.push({ method: req.method, body: bytes.length ? JSON.parse(bytes) : null,\\n        path: target.pathname, version: target.searchParams.get('version'),\\n        paymentHeader: req.headers['payment-signature'] });\\n      if (['POST', 'PUT'].includes(req.method)) item = JSON.parse(bytes);\\n      if (req.method === 'PATCH') item = { ...item, ...JSON.parse(bytes) };\\n      if (req.method === 'DELETE') { item = null; res.writeHead(204); res.end(); return; }\\n      const body = Buffer.from(JSON.stringify({ item }));\\n      res.writeHead(200, { 'content-type': 'application/json', 'content-length': body.length });\\n      res.end(req.method === 'HEAD' ? undefined : body);\\n    } catch { res.writeHead(500); res.end(); }\\n  });\\n  await new Promise((done, fail) => { backend.once('error', fail); backend.listen(0, '127.0.0.1', done); });\\n  backends.push(backend);\\n  const upstreams = { schema: 'stellar-forge.seller-upstreams.v1', bindings: Object.fromEntries(methods.map(method =>\\n    [method.toLowerCase() + 'Item', { origin: `http://127.0.0.1:${backend.address().port}`,\\n      path: '/items/:sku', method, query: ['version'], responseMode: 'json',\\n      availability: { failureThreshold: 3, resetAfterMs: 100, maxResetAfterMs: 1000 } }])) };\\n  await json(join(root, 'upstreams.json'), upstreams);\\n  await importService(['--spec', join(root, 'spec.json'), '--config', join(root, 'selections.json'),\\n    '--service-bindings', join(root, 'bindings.json'), '--upstream-bindings', join(root, 'upstreams.json'),\\n    '--out', join(root, 'service')]);\\n  const config = await readSellerConfig(join(root, 'service', 'seller-service.json'));\\n  assert.deepEqual(config.routes.map(route => route.offer.extensions.bazaar.info.input.method), methods);\\n  for (const route of config.routes) assert.deepEqual(route.offer.accepts, options);\\n  const contractedUpstreams = await parsed(join(root, 'service', 'upstreams.json'));\\n  assert.deepEqual(Object.values(contractedUpstreams.bindings).map(binding => binding.responseContract.method), methods);\\n  const application = createUpstreamApplication(config, contractedUpstreams, { allowLoopback: true });\\n  const handlers = application.handlers;\\n\\n  // The actual challenge-only service carries every imported method through its\\n  // developer projection, original route audit and private support capture.\\n  const challengeSeller = await startSellerService({ config: application.config, handlers, port: 0 });\\n  challengeSeller.upstreamSnapshot = application.snapshot;\\n  sessions.push(challengeSeller);\\n  const challengeOps = await startSellerOperations(challengeSeller, { port: 0 });\\n  sessions.push(challengeOps);\\n  const openapi = JSON.parse((await response(challengeSeller.url + '/_seller/openapi.json')).body);\\n  const exposed = openapi.paths['/api/items/{sku}'];\\n  assert.deepEqual(Object.keys(exposed).sort(), methods.map(method => method.toLowerCase()).sort());\\n  for (const method of methods) assert.equal(Boolean(exposed[method.toLowerCase()].requestBody), requiresJsonBody(method));\\n  const planning = challengeSeller.compiled.routes.map(route => ({ id: route.id, method: route.method,\\n    advertisedUrl: route.offer.resource.url, template: route.path, offer: route.offer }));\\n  assert.ok(planProbes(planning).filter(plan => ['PUT', 'PATCH', 'DELETE'].includes(plan.route.method)).every(plan => plan.skip));\\n  const cases = { schema: 'scf.sf96.operator-cases.v1', routes: Object.fromEntries(methods.map(method =>\\n    [method.toLowerCase() + 'Item', { path: '/api/items/SKU-1', query: { version: 1 },\\n      ...(method === 'POST' ? { allowPost: true } : {}),\\n      ...(['PUT', 'PATCH', 'DELETE'].includes(method) ? { allowMethod: method } : {}),\\n      ...(requiresJsonBody(method) ? { body: { quantity: 1 } } : {}),\\n    }])) };\\n  await json(join(root, 'cases.json'), cases);\\n  const audit = await auditSeller({ seller: challengeSeller.url, casesPath: join(root, 'cases.json'), out: join(root, 'audit') });\\n  assert.deepEqual(audit.summary, { total: 6, passed: 6, blocked: 0, needsInput: 0 });\\n  assert.equal(observed.length, 0, 'challenge-only routes must not invoke backend');\\n  await captureBundle({ seller: challengeSeller.url, ops: challengeOps.url, out: join(root, 'support') });\\n  const support = await parsed(join(root, 'support', 'bundle.json'));\\n  assert.deepEqual(support.seller.advertisedRoutes.map(route => route.method), methods);\\n  assert.equal(support.observation.totals.challenge, 6);\\n\\n  const native = { entered: 0, settled: 0 };\\n  const nativeSeller = await startSellerService({ config: application.config, handlers, port: 0, nativeFactory: async () => ({\\n    async processHTTPRequest(context) {\\n      native.entered++;\\n      if (context.paymentHeader !== 'LOCAL_CONTROLLED_PAYMENT')\\n        return { type: 'payment-error', response: { status: 402, body: { error: 'CONTROLLED_PAYMENT_REQUIRED' } } };\\n      return { type: 'payment-verified', cancellationDispatcher: { cancel: async () => ({}) },\\n        paymentPayload: {}, paymentRequirements: {}, declaredExtensions: {} };\\n    },\\n    async processSettlement() { native.settled++; return { success: true, headers: {} }; },\\n    createFailurePathSettlementHeaders() { return {}; },\\n  }) });\\n  nativeSeller.upstreamSnapshot = application.snapshot;\\n  sessions.push(nativeSeller);\\n  const nativeOps = await startSellerOperations(nativeSeller, { port: 0 });\\n  sessions.push(nativeOps);\\n  const target = nativeSeller.url + '/api/items/SKU-1?version=1';\\n  const unsigned = await response(target, { method: 'PUT', headers: { 'content-type': 'application/json' }, body: '{\\\"quantity\\\":2}' });\\n  assert.equal(unsigned.status, 402);\\n  assert.equal(observed.length, 0, 'unpaid native request must not invoke backend');\\n  for (const [method, contentType, body, expected] of [\\n    ['PUT', 'application/json', '{\\\"quantity\\\":-1}', 422],\\n    ['PATCH', 'text/plain', '{\\\"quantity\\\":2}', 415],\\n    ['DELETE', 'application/json', '{\\\"quantity\\\":2}', 400],\\n  ]) {\\n    const result = await response(target, { method, headers: { 'content-type': contentType }, body });\\n    assert.equal(result.status, expected, method + ' prepayment rejection');\\n  }\\n  assert.equal(native.entered, 1, 'invalid inputs must stop before native payment');\\n  for (const [index, method] of methods.entries()) {\\n    const result = await response(target, { method,\\n      headers: { 'payment-signature': 'LOCAL_CONTROLLED_PAYMENT',\\n        ...(requiresJsonBody(method) ? { 'content-type': 'application/json' } : {}) },\\n      ...(requiresJsonBody(method) ? { body: JSON.stringify({ quantity: index + 1 }) } : {}),\\n    });\\n    assert.equal(result.status, method === 'DELETE' ? 204 : 200, method + ' delivery');\\n    if (method === 'HEAD' || method === 'DELETE') assert.equal(result.body, '');\\n  }\\n  assert.equal(item, null);\\n  assert.deepEqual(observed.map(row => row.method), methods);\\n  assert.ok(observed.every(row => row.path === '/items/SKU-1' && row.version === '1' && row.paymentHeader === undefined));\\n  assert.deepEqual(observed.map(row => row.body), [null, null, { quantity: 3 }, { quantity: 4 }, { quantity: 5 }, null]);\\n  assert.equal(native.settled, 6);\\n  assert.ok(application.snapshot().bindings.every(binding => binding.protected && binding.completed === 1));\\n  const traffic = nativeOps.observer.snapshot();\\n  assert.equal(traffic.routes.find(row => row.id === '@method').started, 0);\\n  assert.ok(traffic.routes.filter(row => !row.id.startsWith('@')).every(row => row.success === 1));\\n  console.log(JSON.stringify({ status: 'PASS', methods, importedRoutes: 6,\\n    originalChallengeAcceptance: audit.summary, upstreamRequests: observed.length,\\n    prepaymentRejections: 3, nativeSettlements: '6 controlled collaborator calls; no ledger payment',\\n    supportMethodCoverage: 6, responseContracts: 6, protectedUpstreams: 6,\\n    paymentAlternativesPerRoute: options.length, hostedActions: 0 }));\\n} finally {\\n  for (const session of sessions.reverse()) await session.close();\\n  for (const backend of backends) await new Promise(resolve => {\\n    backend.close(resolve); backend.closeIdleConnections?.();\\n  });\\n  await rm(root, { recursive: true, force: true });\\n}\\n\"},{\"sha\":\"588e57e34b8b134f537dead8a1eeecc05b838067\",\"paths\":[\"stellar/scf-starforge-20261009/sf30-seller-sdk/streaming-journey.mjs\"],\"source\":\"// MIT. One native HTTP streaming journey, reusing the original SDK and buyer.\\n// The facilitator is the existing local outcome fixture; no chain calls.\\nimport assert from 'node:assert/strict';\\nimport { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';\\nimport { tmpdir } from 'node:os';\\nimport { join, resolve, dirname } from 'node:path';\\nimport { fileURLToPath } from 'node:url';\\nimport { createHash } from 'node:crypto';\\nimport { setTimeout as delay } from 'node:timers/promises';\\nimport { startStreamingBackend } from './examples/streaming-backend.mjs';\\nimport { createUpstreamApplication } from './upstream.mjs';\\nimport { createNativeSellerServer } from './native-factory.mjs';\\nimport { startSellerService } from './serve.mjs';\\nimport { streamingResponse } from './stream-response.mjs';\\nimport { X402BuyerClient } from '../sf31-buyer-client/buyer.mjs';\\nimport { prepareBuyerResponseFile } from '../sf31-buyer-client/response-file.mjs';\\nimport { BuyerResult } from '../sf88-operator-buyer-cli/node/result.mjs';\\n\\nconst root = dirname(fileURLToPath(import.meta.url));\\nconst directory = await mkdtemp(join(tmpdir(), 'sf30-stream-journey-'));\\nconst selected = process.argv.includes('--case') ? process.argv[process.argv.indexOf('--case') + 1] : null;\\nconst report = { schema: 'stellar-forge.native-stream-journey.v1', cases: {},\\n  runtime: process.version, nativeSdk: '2.28.0', facilitator: 'existing-local-outcome-fixture' };\\nconst counts = { verify: 0, settle: 0, approved: 0, signed: 0 };\\nconst settlements = [];\\nlet refuse = false, malformedClosed = 0, seller, application;\\nconst backend = await startStreamingBackend({ port: 0 });\\nconst config = JSON.parse(await readFile(join(root, 'examples/streaming-service.json'), 'utf8'));\\nconst bindings = JSON.parse(await readFile(join(root, 'examples/streaming-upstreams.json'), 'utf8'));\\nfor (const value of Object.values(bindings.bindings)) value.origin = backend.url;\\nconst malformedRoute = { id: 'malformed-records', path: '/malformed', handler: 'malformed',\\n  definition: { method: 'GET', responseFormat: 'ndjson', description: 'Local malformed-source failure case',\\n    payment: structuredClone(config.routes[1].definition.payment), outputExample: { record: 1 } } };\\nconst facilitator = {\\n  async getSupported() {\\n    return { kinds: [{ x402Version: 2, scheme: 'exact', network: 'stellar:testnet' }],\\n      extensions: ['bazaar'], signers: {} };\\n  },\\n  async verify() { counts.verify++; return { isValid: true, payer: 'LOCAL_STREAM_JOURNEY' }; },\\n  async settle(_payload, requirements) {\\n    counts.settle++;\\n    settlements.push({ flow: requirements.extra?.paymentFlow ?? 'authorization',\\n      source: backend.snapshot(), refused: refuse });\\n    return refuse ? { success: false, network: 'stellar:testnet', transaction: '',\\n      errorReason: 'LOCAL_STREAM_JOURNEY_DECLINED' } :\\n      { success: true, network: 'stellar:testnet',\\n        transaction: createHash('sha256').update('LOCAL_STREAM_JOURNEY_' + counts.settle).digest('hex'),\\n        payer: 'LOCAL_STREAM_JOURNEY' };\\n  },\\n};\\nconst buyer = new X402BuyerClient({ allowLocal: true });\\nconst signs = {\\n  approve: async intent => {\\n    assert.ok(Object.isFrozen(intent.acceptedTerms));\\n    counts.approved++; return true;\\n  },\\n  sign: async ({ challenge, accepted }) => {\\n    counts.signed++;\\n    return { x402Version: 2, resource: challenge.resource, accepted,\\n      extensions: challenge.extensions, payload: { fixture: 'LOCAL_ONLY_NO_SIGNATURE' } };\\n  },\\n};\\nconst expectation = flow => ({ scheme: 'exact', network: 'stellar:testnet',\\n  asset: 'UNVERIFIED_DEMO_ASSET', payTo: 'UNVERIFIED_DEMO_RECIPIENT',\\n  maxAtomic: '10000', maxTimeoutSeconds: 120,\\n  ...(flow ? { paymentFlow: flow } : {}) });\\nconst reader = (native, delivery, selectedFile) => {\\n  const { response, ...original } = native;\\n  return new BuyerResult({ native: { ...original, responseFile: delivery },\\n    exitCode: null, exitSignal: null, runtimeError: 'DIRECT_SF31_CAPTURE', recovered: false },\\n  selectedFile, resolve(root, '../sf88-operator-buyer-cli'));\\n};\\nconst persist = async () => {\\n  report.observed = { ...counts, backend: backend.snapshot() };\\n  if (process.argv.includes('--out')) {\\n    const destination = resolve(process.argv[process.argv.indexOf('--out') + 1]);\\n    await writeFile(destination, JSON.stringify(report, null, 2) + '\\\\n');\\n  }\\n};\\nconst run = async (name, action) => {\\n  if (selected && !selected.split(',').includes(name)) return;\\n  try { report.cases[name] = { status: 'PASS', ...await action() }; }\\n  catch (error) {\\n    report.cases[name] = { status: 'FAIL', code: error.code ?? error.name, message: error.message };\\n    await persist(); throw error;\\n  }\\n  await persist();\\n};\\ntry {\\n  application = createUpstreamApplication(config, bindings, { allowLoopback: true });\\n  application.config.routes.push(malformedRoute);\\n  seller = await startSellerService({ config: application.config, port: 0,\\n    handlers: { ...application.handlers, malformed: async () => streamingResponse({\\n      format: 'ndjson', body: (async function* () {\\n        yield Buffer.from('{\\\"record\\\":1}\\\\n'); yield Buffer.from('not-json\\\\n');\\n      })(), close() { malformedClosed++; },\\n    }) },\\n    nativeFactory: compiled => createNativeSellerServer(compiled, { facilitatorClient: facilitator }) });\\n\\n  await run('explicit-upfront-selection', async () => {\\n    const before = { ...counts }, source = backend.snapshot();\\n    await assert.rejects(() => buyer.call({ url: seller.url + '/metrics/events?count=2&intervalMs=10',\\n      expect: expectation(), ...signs }), error => error.code === 'PAYMENT_TERMS_NOT_AUTHORIZED');\\n    assert.deepEqual(counts, before);\\n    assert.deepEqual(backend.snapshot(), source);\\n    return { approvalCalls: 0, signerCalls: 0, sourceCalls: 0 };\\n  });\\n\\n  await run('live-upfront-sse', async () => {\\n    const before = { ...counts }, source = backend.snapshot(), records = [];\\n    const options = { destination: join(directory, 'telemetry.sse'), maxBytes: 1024 * 1024,\\n      timeoutMs: 10000, stream: { format: 'sse' } };\\n    const prepared = await prepareBuyerResponseFile(options);\\n    const result = await buyer.call({ url: seller.url + '/metrics/events?count=6&intervalMs=200',\\n      expect: expectation('upfront'), ...signs });\\n    assert.equal(result.httpStatus, 200);\\n    assert.equal(result.settlement, 'REPORTED_SUCCESS', result.reason ?? 'Expected native receipt');\\n    assert.equal(result.receipt.success, true);\\n    let firstSource;\\n    const saved = await prepared.save(result, { onRecord(record) {\\n      firstSource ??= backend.snapshot(); records.push(record);\\n    } });\\n    assert.equal(saved.stream.complete, true); assert.equal(records.length, 7);\\n    assert.equal(counts.verify - before.verify, 0);\\n    assert.equal(counts.settle - before.settle, 1);\\n    assert.equal(settlements.at(-1).source.requests, source.requests);\\n    assert.equal(firstSource.completed, source.completed);\\n    assert.ok(JSON.parse(records[0].data).residentBytes > 0);\\n    const bytes = await readFile(saved.path);\\n    assert.equal(saved.sha256, createHash('sha256').update(bytes).digest('hex'));\\n    const reopened = reader(result, { status: 'SAVED', ...saved }, options), recovered = [];\\n    for await (const event of reopened.events()) recovered.push(event);\\n    assert.deepEqual(recovered, records);\\n    return { records: records.length, bytes: saved.bytes, sha256: saved.sha256,\\n      originalSettlements: 1, firstRecordBeforeGenerationCompleted: true, reopened: true };\\n  });\\n\\n  await run('authorization-ndjson', async () => {\\n    const before = { ...counts }, source = backend.snapshot();\\n    const options = { destination: join(directory, 'telemetry.ndjson'), maxBytes: 1024 * 1024,\\n      timeoutMs: 10000, stream: { format: 'ndjson' } };\\n    const prepared = await prepareBuyerResponseFile(options);\\n    const result = await buyer.call({ url: seller.url + '/metrics/records', method: 'POST',\\n      headers: { 'content-type': 'application/json' },\\n      body: JSON.stringify({ count: 4, intervalMs: 20 }), expect: expectation(), ...signs });\\n    assert.equal(result.httpStatus, 200);\\n    assert.equal(settlements.at(-1).source.completed, source.completed + 1);\\n    const saved = await prepared.save(result);\\n    assert.equal(counts.verify - before.verify, 1); assert.equal(counts.settle - before.settle, 1);\\n    const reopened = reader(result, { status: 'SAVED', ...saved }, options), records = [];\\n    for await (const record of reopened.ndjson()) records.push(record);\\n    assert.equal(records.length, 5); assert.equal(records.at(-1).samples, 4);\\n    return { records: records.length, bytes: saved.bytes,\\n      generationCompletedBeforeSettlement: true, reopened: true };\\n  });\\n\\n  await run('cancel-and-reopen-partial', async () => {\\n    const before = { ...counts }, source = backend.snapshot(), controller = new AbortController();\\n    const options = { destination: join(directory, 'partial.sse'), maxBytes: 1024 * 1024,\\n      timeoutMs: 10000, stream: { format: 'sse' } };\\n    const prepared = await prepareBuyerResponseFile(options);\\n    const result = await buyer.call({ url: seller.url + '/metrics/events?count=30&intervalMs=50',\\n      expect: expectation('upfront'), signal: controller.signal, ...signs });\\n    let observed = 0, failure;\\n    try { await prepared.save(result, { signal: controller.signal, onRecord() {\\n      observed++; if (observed === 3) controller.abort();\\n    } }); } catch (error) { failure = error; }\\n    assert.ok(failure?.partialPath); assert.equal(failure.stream.complete, false);\\n    assert.ok(failure.bytes > 0); assert.ok(failure.partialSha256);\\n    const delivery = { status: 'FAILED', code: failure.code, bytes: failure.bytes,\\n      partialPath: failure.partialPath, partialSha256: failure.partialSha256, stream: failure.stream };\\n    const reopened = reader(result, delivery, options), records = [];\\n    for await (const event of reopened.events({ allowPartial: true })) records.push(event);\\n    // A transport chunk may contain more fully retained records than the\\n    // callback visited before cancellation. Reopen the exact stored prefix.\\n    assert.equal(records.length, failure.stream.records);\\n    assert.ok(records.length >= observed);\\n    assert.ok(records.length < 31);\\n    assert.equal(counts.settle - before.settle, 1);\\n    assert.equal(result.receipt.success, true);\\n    await delay(40);\\n    assert.equal(backend.snapshot().active, 0);\\n    assert.equal(backend.snapshot().cancelled, source.cancelled + 1);\\n    return { retainedRecords: records.length, retainedBytes: failure.bytes,\\n      partialSha256: failure.partialSha256, sourceCancelled: true, originalSettlements: 1 };\\n  });\\n\\n  await run('settlement-refusal', async () => {\\n    const source = backend.snapshot(), before = { ...counts };\\n    refuse = true;\\n    let result;\\n    try { result = await buyer.call({ url: seller.url + '/metrics/events?count=2&intervalMs=10',\\n      expect: expectation('upfront'), ...signs }); }\\n    finally { refuse = false; }\\n    assert.equal(result.httpStatus, 402);\\n    await result.response.body?.cancel();\\n    assert.deepEqual(backend.snapshot(), source);\\n    assert.equal(counts.settle - before.settle, 1);\\n    return { sourceCalls: 0, receiptStatus: result.settlement };\\n  });\\n\\n  await run('malformed-authorization-source', async () => {\\n    const before = { ...counts }, closed = malformedClosed;\\n    const result = await buyer.call({ url: seller.url + '/malformed',\\n      expect: expectation(), ...signs });\\n    assert.equal(result.httpStatus, 500);\\n    await result.response.body?.cancel();\\n    assert.equal(counts.verify - before.verify, 1);\\n    assert.equal(counts.settle - before.settle, 0);\\n    assert.equal(malformedClosed, closed + 1);\\n    return { originalSettlements: 0, originalSourceClosed: true };\\n  });\\n  if (selected && selected.split(',').some(name => !Object.hasOwn(report.cases, name)))\\n    throw new Error('Unknown --case');\\n  report.status = 'PASS';\\n} finally {\\n  await seller?.close();\\n  await application?.close();\\n  await backend.close();\\n  await rm(directory, { recursive: true, force: true });\\n  await persist();\\n}\\nconsole.log(JSON.stringify(report, null, 2));\\n\\n\"},{\"sha\":\"cf9e92aed634a389f77f52a3ee2a8c1f6d32c2d2\",\"paths\":[\"stellar/scf-starforge-20261009/sf30-seller-sdk/upstream-acceptance.mjs\"],\"source\":\"// MIT. One real loopback HTTP acceptance for the upstream application handler.\\n// No facilitator mock, blockchain receipt, external request, or SDK claim.\\nimport assert from 'node:assert/strict';\\nimport { createServer } from 'node:http';\\nimport { gzipSync } from 'node:zlib';\\nimport { createUpstreamHandler } from './upstream-handler.mjs';\\n\\nconst seen = [], observations = [];\\nlet slow = true, credential = 'local-fixture-one';\\nconst server = createServer(async (req, res) => {\\n  const parts = []; for await (const part of req) parts.push(part);\\n  const item = { method: req.method, path: req.url, headers: req.headers, body: Buffer.concat(parts).toString() };\\n  seen.push(item);\\n  const path = new URL(req.url, 'http://localhost').pathname;\\n  if (path.endsWith('/slow') && slow) return;\\n  if (path.endsWith('/redirect')) { res.writeHead(302, { location: '/never-follow' }); res.end(); return; }\\n  if (path.endsWith('/error')) { res.writeHead(503, { 'retry-after': '7' }); res.end('private upstream stack + credential'); return; }\\n  if (path.endsWith('/nested-payment')) { res.writeHead(402, { 'payment-required': 'secret' }); res.end(); return; }\\n  if (path.endsWith('/auth')) { res.writeHead(401); res.end('private auth failure'); return; }\\n  res.setHeader('content-type', 'application/json; charset=utf-8');\\n  res.setHeader('set-cookie', 'private-session=fixture');\\n  res.setHeader('payment-response', 'not-a-settlement');\\n  res.setHeader('x-internal-secret', 'fixture');\\n  res.setHeader('connection', 'close, x-hop-only');\\n  res.setHeader('x-hop-only', 'transport-only');\\n  if (path.endsWith('/gzip') || path.endsWith('/large')) {\\n    res.setHeader('content-encoding', 'gzip');\\n    res.end(gzipSync(JSON.stringify({ value: path.endsWith('/large') ? 'x'.repeat(8192) : 'original bytes' }))); return;\\n  }\\n  if (path.endsWith('/broken')) { res.end('{not JSON'); return; }\\n  if (path.endsWith('/partial')) { res.setHeader('content-length', '999'); res.end('{\\\"ok\\\":true}'); return; }\\n  res.end(JSON.stringify({ ok: true, method: req.method, body: item.body ? JSON.parse(item.body) : null }));\\n});\\nawait new Promise(resolve => server.listen(0, '127.0.0.1', resolve));\\nconst baseUrl = `http://127.0.0.1:${server.address().port}/v1`;\\nconst make = (path, extra = {}) => createUpstreamHandler({ baseUrl, path, allowLocal: true, ...extra });\\nconst ctx = (method = 'GET', params = {}, query = '') => ({ method, pathParams: params,\\n  url: new URL(`https://seller.example/resource${query}`), headers: {}, body: null });\\ntry {\\n  const handler = make('/items/:id', { query: { city: 'q', tag: 'tag' }, requestHeaders: ['accept-language', 'x-hop-only'], responseHeaders: ['content-type', 'x-hop-only'],\\n    headers: () => ({ Authorization: `Bearer ${credential}` }), onResult: e => observations.push(e) });\\n  const request = ctx('GET', { id: 'Clé 1' }, '?city=Louisville&tag=a&tag=b');\\n  request.headers = { authorization: 'buyer-credential', cookie: 'buyer-cookie',\\n    'payment-signature': 'buyer-payment', 'x-forwarded-host': 'attacker', 'accept-language': 'fr', connection: 'x-hop-only', 'x-hop-only': 'transport-only' };\\n  const first = await handler(request);\\n  assert.equal(first.status, 200); assert.equal(JSON.parse(first.body).ok, true);\\n  assert.equal(seen.at(-1).path, '/v1/items/Cl%C3%A9%201?q=Louisville&tag=a&tag=b');\\n  assert.equal(seen.at(-1).headers.authorization, 'Bearer local-fixture-one');\\n  for (const name of ['cookie', 'payment-signature', 'x-forwarded-host', 'x-hop-only']) assert.equal(seen.at(-1).headers[name], undefined);\\n  assert.equal(seen.at(-1).headers['accept-language'], 'fr');\\n  for (const name of ['set-cookie', 'payment-response', 'x-internal-secret', 'x-hop-only']) assert.equal(first.headers[name], undefined);\\n  credential = 'local-fixture-two'; await handler(request);\\n  assert.equal(seen.at(-1).headers.authorization, 'Bearer local-fixture-two');\\n  const count = seen.length;\\n  assert.equal((await handler(ctx('GET', { id: '..' }))).status, 400);\\n  assert.equal((await handler(ctx('GET', { id: 'a/b' }))).status, 400);\\n  assert.equal((await handler(ctx('GET', { id: 'a' }, '?undeclared=1'))).status, 400);\\n  assert.equal(seen.length, count);\\n  assert.throws(() => make('/items', { requestHeaders: ['authorization'] }));\\n  assert.throws(() => make('/items', { responseHeaders: ['payment-response'] }));\\n  assert.throws(() => make('/items', { headers: { 'PAYMENT-SIGNATURE': 'fixture' } }));\\n  const lookups = [];\\n  const pinned = createUpstreamHandler({ baseUrl: baseUrl.replace('127.0.0.1', 'localhost'),\\n    path: '/pinned', allowLocal: true,\\n    lookup(hostname, options, callback) {\\n      lookups.push({ hostname, all: options.all === true });\\n      if (options.all) callback(null, [{ address: '127.0.0.1', family: 4 }]);\\n      else callback(null, '127.0.0.1', 4);\\n    } });\\n  assert.equal((await pinned(ctx())).status, 200);\\n  assert.equal(lookups.length, 1); assert.equal(lookups[0].hostname, 'localhost');\\n  assert.equal(seen.at(-1).headers.host, `localhost:${server.address().port}`);\\n  const unresolved = createUpstreamHandler({ baseUrl: baseUrl.replace('127.0.0.1', 'localhost'),\\n    path: '/never-resolved', allowLocal: true, timeoutMs: 100, lookup() {} });\\n  const beforeLookup = seen.length;\\n  assert.equal((await unresolved(ctx())).body.error, 'UPSTREAM_TIMEOUT');\\n  assert.equal(seen.length, beforeLookup);\\n  assert.throws(() => make('/items', { lookup: 'not-a-function' }));\\n  console.log('PASS path/query mapping, credential rotation, header isolation, trusted lookup, preflight');\\n\\n  const post = make('/score', { method: 'POST' }), input = ctx('POST');\\n  input.body = { nested: ['é', 3], flag: false };\\n  assert.deepEqual(JSON.parse((await post(input)).body).body, input.body);\\n  assert.deepEqual(JSON.parse(seen.at(-1).body), input.body);\\n  assert.equal(seen.at(-1).method, 'POST');\\n  input.body = null; assert.equal(JSON.parse((await post(input)).body).body, null);\\n  const head = await make('/score', { method: 'HEAD' })(ctx('HEAD'));\\n  assert.equal(head.status, 200); assert.equal(head.body.length, 0);\\n  const compressed = await make('/gzip')(ctx());\\n  assert.deepEqual(JSON.parse(compressed.body), { value: 'original bytes' });\\n  assert.equal(compressed.headers['content-encoding'], undefined);\\n  console.log('PASS JSON POST/null, HEAD, compressed JSON byte delivery');\\n\\n  const refusals = { redirect: 'UPSTREAM_REDIRECT_REFUSED', error: 'UPSTREAM_REQUEST_FAILED',\\n    'nested-payment': 'UPSTREAM_PAYMENT_REQUIRED', auth: 'UPSTREAM_AUTH_FAILED',\\n    broken: 'UPSTREAM_JSON_INVALID', partial: 'UPSTREAM_RESPONSE_INCOMPLETE', large: 'UPSTREAM_RESPONSE_TOO_LARGE' };\\n  for (const [path, expected] of Object.entries(refusals)) {\\n    const count = seen.length;\\n    const result = await make('/' + path, { timeoutMs: 1000, maxResponseBytes: 1024 })(ctx());\\n    assert.equal(result.body.error, expected, path);\\n    assert.equal(seen.length, count + 1, 'one request, no retries');\\n    assert.ok(!JSON.stringify(result).includes('private upstream'));\\n    if (path === 'error') assert.equal(result.headers['retry-after'], '7');\\n  }\\n  assert.ok(!seen.some(item => item.path === '/never-follow'));\\n  console.log('PASS sanitized upstream failures, redirects, partial/oversized body, no retries');\\n\\n  const bounded = make('/slow', { timeoutMs: 100, maxInFlight: 1 });\\n  const pending = bounded(ctx());\\n  assert.equal((await bounded(ctx())).body.error, 'UPSTREAM_CAPACITY_EXHAUSTED');\\n  assert.equal((await pending).body.error, 'UPSTREAM_TIMEOUT');\\n  slow = false;\\n  assert.equal((await bounded(ctx())).status, 200);\\n  assert.deepEqual(bounded.snapshot(), { started: 2, completed: 2, inFlight: 0, failed: 1, timedOut: 1,\\n    responseBytes: Buffer.byteLength(JSON.stringify({ ok: true, method: 'GET', body: null })) });\\n  assert.ok(observations.length === 2 && !JSON.stringify(observations).includes('fixture'));\\n  console.log('PASS full response deadline, capacity recovery, content-free metrics');\\n  console.log(JSON.stringify({ result: 'PASS', groups: 4, upstreamRequests: seen.length, externalRequests: 0,\\n    scope: 'real Node HTTP upstream handler; payment SDK integration not executed by this runner' }));\\n} finally {\\n  server.closeAllConnections();\\n  await new Promise(resolve => server.close(resolve));\\n}\\n\"},{\"sha\":\"6afb607f2da928f1b9ab2cd8ad24115fcc7ee686\",\"paths\":[\"stellar/scf-starforge-20261009/sf30-seller-sdk/upstream-readiness-acceptance.mjs\"],\"source\":\"// MIT. One original-source availability journey; native SDK + real loopback HTTP.\\n// Facilitator outcomes below are controlled local responses, NOT chain payments.\\nimport assert from 'node:assert/strict';\\nimport { createServer } from 'node:http';\\nimport { setTimeout as delay } from 'node:timers/promises';\\nimport { encodePaymentSignatureHeader } from '@x402/core/http';\\nimport { createNativeSellerServer } from './native-factory.mjs';\\nimport { startSellerService } from './serve.mjs';\\nimport { createUpstreamApplication } from './upstream.mjs';\\nimport { protectUpstream } from './upstream-readiness.mjs';\\nimport { createUpstreamHandler } from './upstream-handler.mjs';\\nimport { startSellerOperations } from './operations/server.mjs';\\n\\nlet backendMode = 'failure', backendCalls = 0, nativeEntries = 0, verified = 0, settled = 0;\\nlet held, observedHold;\\nconst privateMarker = 'Bearer locally-generated-availability-acceptance';\\nconst backend = createServer((req,res) => {\\n  backendCalls++;\\n  assert.equal(req.headers.authorization, privateMarker);\\n  assert.equal(req.headers['payment-signature'], undefined);\\n  const send = status => { if (res.writableEnded) return; res.writeHead(status,{'content-type':'application/json'});\\n    res.end(JSON.stringify(status === 200 ? {rows:[{item:'original backend result'}]} : {privateDiagnostic:privateMarker})); };\\n  if (backendMode === 'held') { held = () => send(200); observedHold?.(); return; }\\n  send(backendMode === 'failure' ? 503 : backendMode === 'client' ? 404 : 200);\\n});\\nawait new Promise(done => backend.listen(0,'127.0.0.1',done));\\nconst origin = `http://127.0.0.1:${backend.address().port}`;\\nconst config = {schema:'stellar-forge.seller-service.v1',publicOrigin:'https://merchant.example',routes:[{\\n  id:'search',path:'/search',handler:'merchantSearch',definition:{method:'GET',description:'Local acceptance query',\\n    queryParameters:[{name:'q',type:'string',description:'Query value',example:'one',required:true}],\\n    payment:{scheme:'exact',network:'stellar:testnet',asset:'UNVERIFIED_LOCAL_ASSET',\\n      payTo:'UNVERIFIED_LOCAL_RECIPIENT',amount:'17000',maxTimeoutSeconds:60}},\\n}]};\\nconst bindings = {schema:'stellar-forge.seller-upstreams.v1',bindings:{merchantSearch:{\\n  origin,path:'/query',query:['q'],headerEnv:{Authorization:'LOCAL_BACKEND_AUTH'},maxInFlight:8,\\n  availability:{failureThreshold:2,resetAfterMs:100,maxResetAfterMs:400},\\n}}};\\nconst beforeConfig = JSON.stringify(config);\\nconst application = createUpstreamApplication(config,bindings,{allowLoopback:true,env:{LOCAL_BACKEND_AUTH:privateMarker}});\\nassert.equal(JSON.stringify(config),beforeConfig);\\nassert.equal(typeof application.handlers[application.config.routes[0].admit],'function');\\nconst facilitator = {\\n  async getSupported() { return {kinds:[{x402Version:2,scheme:'exact',network:'stellar:testnet'}],extensions:['bazaar'],signers:{}}; },\\n  async verify() { verified++; return {isValid:true,payer:'LOCAL_ACCEPTANCE_NO_WALLET'}; },\\n  async settle() { settled++; return {success:true,network:'stellar:testnet',transaction:'LOCAL_ACCEPTANCE_NO_CHAIN',payer:'LOCAL_ACCEPTANCE_NO_WALLET'}; },\\n};\\nlet seller,operations;\\nconst readState = () => application.snapshot().bindings[0].availability;\\ntry {\\n  seller = await startSellerService({config:application.config,handlers:application.handlers,port:0,\\n    nativeFactory:async compiled => {\\n      const native = await createNativeSellerServer(compiled,{facilitatorClient:facilitator});\\n      const original = native.processHTTPRequest.bind(native);\\n      native.processHTTPRequest = (...args) => { nativeEntries++; return original(...args); };\\n      return native;\\n    }});\\n  seller.upstreamSnapshot = application.snapshot;\\n  operations = await startSellerOperations(seller,{port:0});\\n  const target = seller.url+'/search?q=one';\\n  const challengeResponse = await fetch(target);\\n  assert.equal(challengeResponse.status,402);\\n  const challenge = JSON.parse(Buffer.from(challengeResponse.headers.get('payment-required'),'base64').toString());\\n  assert.equal(challenge.accepts[0].amount,'17000');\\n  assert.equal(backendCalls,0); assert.equal(verified,0);\\n  const headers = {'payment-signature':encodePaymentSignatureHeader({x402Version:2,\\n    resource:challenge.resource,accepted:challenge.accepts[0],extensions:challenge.extensions,\\n    payload:{acceptance:'LOCAL_ONLY_NO_SIGNATURE'}})};\\n  const attempt = () => fetch(target,{headers});\\n  for (let i=0;i<2;i++) {\\n    const result = await attempt(); assert.equal(result.status,503);\\n    assert.equal((await result.json()).error,'UPSTREAM_REQUEST_FAILED');\\n  }\\n  assert.equal(backendCalls,2); assert.equal(verified,2); assert.equal(settled,0);\\n  assert.equal(readState().state,'OPEN');\\n  const beforeBlocked = {nativeEntries,verified,backendCalls};\\n  const blocked = await attempt(); assert.equal(blocked.status,429);\\n  assert.match(blocked.headers.get('retry-after'),/^\\\\d+$/);\\n  assert.equal((await blocked.json()).error,'UPSTREAM_CIRCUIT_OPEN');\\n  assert.deepEqual({nativeEntries,verified,backendCalls},beforeBlocked);\\n  const snapshot = await (await fetch(operations.url+'/api/snapshot')).json();\\n  assert.equal(snapshot.upstreams.bindings[0].availability.state,'OPEN');\\n  assert.ok(!JSON.stringify(snapshot).includes(privateMarker));\\n  assert.ok(!JSON.stringify(snapshot).includes(origin));\\n  assert.equal((await fetch(operations.url+'/api/upstreams',{method:'POST'})).status,405);\\n  assert.equal((await fetch(operations.url+'/api/upstreams',{headers:{origin:'https://wrong.example'}})).status,403);\\n\\n  await delay(110);\\n  backendMode = 'held';\\n  const reached = new Promise(done => { observedHold = done; });\\n  const recovering = attempt(); await reached;\\n  assert.equal(readState().state,'RECOVERY_IN_FLIGHT');\\n  const trialCounts = {nativeEntries,verified,backendCalls};\\n  const concurrent = await attempt(); assert.equal(concurrent.status,429);\\n  assert.equal((await concurrent.json()).error,'UPSTREAM_RECOVERY_IN_PROGRESS');\\n  assert.deepEqual({nativeEntries,verified,backendCalls},trialCounts);\\n  held(); const recovered = await recovering;\\n  assert.equal(recovered.status,200); assert.ok(recovered.headers.get('payment-response'));\\n  assert.deepEqual(await recovered.json(),{rows:[{item:'original backend result'}]});\\n  assert.equal(readState().state,'CLOSED'); assert.equal(readState().recovered,1);\\n  backendMode = 'client'; assert.equal((await attempt()).status,404);\\n  assert.equal(readState().failureStreak,0);\\n\\n  // A pre-existing slow success must not close a circuit opened by later failures.\\n  backendMode = 'held';\\n  const slowReached = new Promise(done => { observedHold = done; });\\n  const olderSuccess = attempt(); await slowReached;\\n  backendMode = 'failure';\\n  assert.equal((await attempt()).status,503); assert.equal((await attempt()).status,503);\\n  assert.equal(readState().state,'OPEN');\\n  held(); assert.equal((await olderSuccess).status,200);\\n  assert.equal(readState().state,'OPEN');\\n  await delay(110);\\n  assert.equal((await attempt()).status,503);\\n  assert.ok(readState().retryAfterMs > 100); assert.equal(readState().opens,3);\\n\\n  // Preserve an original application's admission/control interface when wrapping.\\n  const originalHandler = createUpstreamHandler({baseUrl:origin,path:'/query',allowLocal:true});\\n  const decision = {status:409,body:{error:'ORIGINAL_APPLICATION_DECISION'}};\\n  let applicationAdmissions = 0;\\n  originalHandler.admit = () => { applicationAdmissions++; return decision; };\\n  originalHandler.idempotency = {status:() => 'original'};\\n  const composed = protectUpstream(originalHandler,{failureThreshold:2,resetAfterMs:100,maxResetAfterMs:400},{maxInFlight:1});\\n  assert.equal(composed.admit({}),decision); assert.equal(applicationAdmissions,1);\\n  assert.equal(composed.idempotency,originalHandler.idempotency);\\n  console.log(JSON.stringify({result:'PASS',source:'original SF30 seller + upstream + operations + x402 SDK 2.28.0',\\n    backendCalls,nativeEntries,controlledVerifyCalls:verified,controlledSettleCalls:settled,\\n    availability:readState(),externalRequests:0,chainTransactions:0,\\n    contract:'outage blocks before native entry; one recovery; late-success isolation; original admission preserved'}));\\n} finally {\\n  held?.();\\n  if (operations) await operations.close();\\n  if (seller) { seller.server.closeAllConnections(); await seller.close(); }\\n  backend.closeAllConnections(); await new Promise(done => backend.close(done));\\n}\\n\"}]")
